polygon(pill_outer, style=no_border_fill(PASTEL_RED))
draw_round_polyline(pill_outer, width_units=w_pill, color=DARK, closed=True)

polygon(pill_inner, style=no_border_fill(WHITE))
draw_round_polyline(pill_inner, width_units=w_inner, color=DARK, closed=True)

for pts in solid_letters:
    polygon(pts, style=no_border_fill(PASTEL_RED))
    draw_round_polyline(pts, width_units=w_letter, color=DARK, closed=True)

for rings in compound_letters:
    draw_compound_polygon(rings, color=PASTEL_RED)
    for ring in rings:
        draw_round_polyline(ring, width_units=w_letter, color=DARK, closed=True)

save()
